int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    int parity = 0;
    int flow_control = 0;
    char *token;
    char *saveptr;
    char *option_copy = strdup(options);
    int ret = 0;
    struct usb_serial_port *port;

    if (!option_copy) {
        return -ENOMEM;
    }

    token = strtok_r(option_copy, ",", &saveptr);
    while (token) {
        if (strncmp(token, "baud", 4) == 0) {
            baud_rate = atoi(token + 4);
        } else if (strncmp(token, "bits", 4) == 0) {
            data_bits = atoi(token + 4);
        } else if (strncmp(token, "parity", 6) == 0) {
            parity = atoi(token + 6);
        } else if (strncmp(token, "flow", 4) == 0) {
            flow_control = atoi(token + 4);
        }
        token = strtok_r(NULL, ",", &saveptr);
    }

    port = get_usb_serial_port(co->index);
    if (!port) {
        free(option_copy);
        return -ENODEV;
    }

    if (!port->connected) {
        free(option_copy);
        log_error("USB port is not connected\n");
        return -ENODEV;
    }

    ret = open_usb_serial_port(port);
    if (ret < 0) {
        free(option_copy);
        return ret;
    }

    ret = configure_terminal_settings(port, baud_rate, data_bits, parity, flow_control);
    if (ret < 0) {
        close_usb_serial_port(port);
        free(option_copy);
        return ret;
    }

    port->is_console = true;

    free(option_copy);
    return 0;
}

int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    char *token;

    token = strtok(options, ",");
    if (!token) {
        return -EINVAL;
    }

    baud_rate = atoi(token);

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    data_bits = atoi(token);

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    parity = *token;

    token = strtok(NULL, ",");
    if (!token) {
        return -EINVAL;
    }

    flow_control = atoi(token);

    struct usb_serial *serial = get_usb_serial_port(co->index);
    if (!serial) {
        log_error("USB serial port not found for console index %d", co->index);
        return -ENODEV;
    }

    if (!is_usb_port_connected(serial)) {
        log_error("USB port for console index %d is not connected", co->index);
        return -ENODEV;
    }

    if (open_usb_serial(serial) < 0) {
        log_error("Failed to open USB serial port for console index %d", co->index);
        return -EIO;
    }

    if (configure_terminal_settings(serial, baud_rate, data_bits, parity, flow_control) < 0) {
        log_error("Failed to configure terminal settings for console index %d", co->index);
        close_usb_serial(serial);
        return -EIO;
    }

    co->is_system_console = true;
    co->serial_port = serial;

    return 0;
}

int usb_console_configure(struct console *co, char *options) {
    struct usb_serial *serial;
    struct termios tios;
    int baud, bits, ret;
    char parity;
    int flow;

    if (!options || !co) {
        return -EINVAL;
    }

    ret = sscanf(options, "%d %c %d %d", &baud, &parity, &bits, &flow);
    if (ret != 4) {
        return -EINVAL;
    }

    serial = usb_serial_get_by_index(co->index);
    if (!serial) {
        pr_err("Failed to get USB serial port for console index %d\n", co->index);
        return -ENODEV;
    }

    if (!usb_serial_port_is_connected(serial)) {
        pr_err("USB serial port is not connected for console index %d\n", co->index);
        return -ENODEV;
    }

    ret = usb_serial_open(serial);
    if (ret < 0) {
        return ret;
    }

    memset(&tios, 0, sizeof(tios));
    tios.c_cflag = baudrate_to_cfsetispeed(baud) | baudrate_to_cfsetospeed(baud);

    if (parity == 'o') {
        tios.c_cflag |= PARENB | PARODD;
    } else if (parity == 'e') {
        tios.c_cflag |= PARENB;
    } else if (parity == 'n') {
        tios.c_cflag &= ~(PARENB | PARODD);
    }

    if (bits == 7) {
        tios.c_cflag |= CS7;
    } else if (bits == 8) {
        tios.c_cflag |= CS8;
    }

    if (flow == 1) {
        tios.c_cflag |= CRTSCTS;
    }

    ret = tcsetattr(serial->tty, TCSANOW, &tios);
    if (ret < 0) {
        usb_serial_close(serial);
        return ret;
    }

    serial->is_console = true;

    return 0;
}

int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    int ret;
    struct usb_serial *serial_port;

    if (!co || !options) {
        return -EINVAL;
    }

    ret = parse_usb_options(options, &baud_rate, &data_bits, &parity, &flow_control);
    if (ret < 0) {
        return ret;
    }

    serial_port = get_usb_serial_port(co->index);
    if (!serial_port) {
        log_error("Failed to retrieve USB serial port for console index %d", co->index);
        return -ENODEV;
    }

    if (!is_usb_port_connected(serial_port)) {
        log_error("USB port is not connected for console index %d", co->index);
        return -ENODEV;
    }

    ret = open_usb_serial_port(serial_port);
    if (ret < 0) {
        log_error("Failed to open USB serial port for console index %d", co->index);
        return ret;
    }

    ret = configure_usb_serial_settings(serial_port, baud_rate, data_bits, parity, flow_control);
    if (ret < 0) {
        close_usb_serial_port(serial_port);
        log_error("Failed to configure USB serial port for console index %d", co->index);
        return ret;
    }

    co->serial = serial_port;
    serial_port->is_console = 1;

    return 0;
}

int usb_console_setup(struct console *co, char *options) {
    struct usb_serial_port *port;
    int baud = 115200;
    int parity = 0;
    int data_bits = 8;
    int flow_control = 0;
    int error;
    struct usb_serial *serial;

    if (!co) {
        return -EINVAL;
    }

    serial = co->data;
    if (!serial) {
        return -ENODEV;
    }

    port = serial->port[0];
    if (!port) {
        return -ENODEV;
    }

    if (!options) {
        options = "115200n8";
    }

    error = tty_parse_num_and_rest(&options, &baud, &options);
    if (error)
        return error;

    switch (*options) {
        case 'o':
            parity = 1;
            options++;
            break;
        case 'O':
            parity = 2;
            options++;
            break;
        case 'n':
            options++;
            break;
        default:
            return -EINVAL;
    }

    if (*options) {
        data_bits = *options - '0';
        options++;
    }

    if (*options == 'r') {
        flow_control = 1;
        options++;
    }

    if (!port->port.open_count) {
        error = port->open(port, port->port.tty);
        if (error < 0)
            return error;
    }

    if (port->port.tty) {
        struct ktermios *termios = &port->port.tty->termios;

        termios->c_cflag &= ~CLOCAL;
        termios->c_cflag |= CLOCAL;

        termios->c_cflag &= ~(CSIZE | CSTOPB | PARENB | CMSPAR);
        termios->c_cflag |= CS8;
        if (parity == 1) {
            termios->c_cflag |= PARENB;
        } else if (parity == 2) {
            termios->c_cflag |= PARENB | CMSPAR;
        }

        if (data_bits != 8) {
            termios->c_cflag &= ~CSIZE;
            if (data_bits == 7)
                termios->c_cflag |= CS7;
            else if (data_bits == 6)
                termios->c_cflag |= CS6;
            else if (data_bits == 5)
                termios->c_cflag |= CS5;
        }

        if (flow_control)
            termios->c_cflag |= CRTSCTS;

        tty_set_termios(port->port.tty, termios);
    }

    co->flags |= CON_ENABLED;
    return 0;
}
